parameters.jsCode:
// Read directly from webhook body — handles both HTML portal and Tally
const body = $('Webhook').item.json['body'];

// Helper function
function getValue(value) {
  if (Array.isArray(value)) return value.join(', ');
  return value || 'Not provided';
}

// Try HTML portal flat structure first then Tally nested structure
const fullName = getValue(body['fullName'] || body?.['data']?.['fields']?.find(f => f['label'] === 'Full Name')?.['value']);
const businessName = getValue(body['businessName'] || body?.['data']?.['fields']?.find(f => f['label'] === 'Business Name')?.['value']);
const email = getValue(body['email'] || body?.['data']?.['fields']?.find(f => f['label'] === 'Email Address')?.['value']);
const phone = getValue(body['phone'] || body?.['data']?.['fields']?.find(f => f['label'] === 'Phone Number')?.['value']);
const revenue = getValue(body['revenue'] || body?.['data']?.['fields']?.find(f => f['label'] === 'What is your monthly revenue?')?.['value']);
const challenge = getValue(body['challenge'] || body?.['data']?.['fields']?.find(f => f['label'] === 'What is your biggest challenge?')?.['value']);
const budget = getValue(body['budget'] || body?.['data']?.['fields']?.find(f => f['label'] === 'What is your budget for this solution?')?.['value']);
const situation = getValue(body['situation'] || body?.['data']?.['fields']?.find(f => f['label'] === 'Tell us more about your situation')?.['value']);

// Get AI response from Edit Fields1
const rawText = $input.item.json['rawAIText'];

const cleanedText = rawText
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleanedText);
} catch(e) {
  parsed = {
    score: "Warm",
    confidence: "Low",
    reason: "Could not parse AI response",
    recommended_action: "Follow up within 24 hours",
    budget_assessment: "Unknown",
    urgency: "Medium"
  };
}

const score = parsed['score'] || 'Warm';

let scoreEmoji;
let borderColor;
let emailPrefix;
let followUpTime;

if (score === 'Hot') {
  scoreEmoji = '🔥';
  borderColor = '#e74c3c';
  emailPrefix = '🔥 HOT LEAD';
  followUpTime = 'Call within 2 hours';
} else if (score === 'Warm') {
  scoreEmoji = '🌤️';
  borderColor = '#f39c12';
  emailPrefix = '🌤️ WARM LEAD';
  followUpTime = 'Follow up within 24 hours';
} else {
  scoreEmoji = '❄️';
  borderColor = '#3498db';
  emailPrefix = '❄️ COLD LEAD';
  followUpTime = 'Add to newsletter list';
}

return {
  fullName: fullName,
  businessName: businessName,
  email: email,
  phone: phone,
  revenue: revenue,
  challenge: challenge,
  budget: budget,
  situation: situation,
  score: score,
  scoreEmoji: scoreEmoji,
  borderColor: borderColor,
  emailPrefix: emailPrefix,
  followUpTime: followUpTime,
  confidence: parsed['confidence'] || 'Medium',
  reason: parsed['reason'] || 'No reason provided',
  recommendedAction: parsed['recommended_action'] || 'Follow up',
  budgetAssessment: parsed['budget_assessment'] || 'Unknown',
  urgency: parsed['urgency'] || 'Medium',
  submittedAt: new Date().toLocaleString('en-ZA', { timeZone: 'Africa/Johannesburg' })
};

